import Foundation
import MapCore
import Testing

@testable import MapStudy

/// FSRS-6 conformance against the reference vectors (SPEC §14, §10).
///
/// The fixture was generated by `ts-fsrs@6.0.0` (see `Fixtures/README.md`):
/// stability/difficulty/retrievability match to 1e-4 relative; due dates,
/// scheduled days, reps, lapses, learning steps and states match exactly.
struct FSRSReferenceVectorTests {
    private let dateStyle = Date.ISO8601FormatStyle(includingFractionalSeconds: true)

    private struct Fixture: Codable {
        struct Generator: Codable {
            let tool: String
            let version: String
            let fuzz: Bool
            let weights: [Double]
        }

        struct Scenario: Codable {
            struct Step: Codable {
                struct CardOut: Codable {
                    let due: String
                    let stability: Double
                    let difficulty: Double
                    let scheduledDays: Double
                    let reps: Int
                    let lapses: Int
                    let learningSteps: Int
                    let state: String
                    let lastReview: String?
                }
                let grade: String
                let ts: String
                let stateBefore: String
                let retrievabilityBefore: Double
                let elapsedDaysBefore: Double
                let card: CardOut
            }

            struct Probe: Codable {
                let ts: String
                let value: Double
            }

            let name: String
            let steps: [Step]
            let retrievabilityProbes: [Probe]?
        }

        let generator: Generator
        let scenarios: [Scenario]
    }

    private func loadFixture() throws -> Fixture {
        let url = Bundle.module.url(forResource: "fsrs6-vectors", withExtension: "json", subdirectory: "Fixtures")
        let data = try Data(contentsOf: try #require(url))
        return try JSONDecoder().decode(Fixture.self, from: data)
    }

    private func date(_ iso: String) throws -> Date {
        try #require(try? Date(iso, strategy: dateStyle))
    }

    private func close(_ actual: Double, _ expected: Double, context: String) {
        let tolerance = max(1e-4 * abs(expected), 1e-12)
        #expect(abs(actual - expected) <= tolerance, "\(context): \(actual) vs \(expected)")
    }

    @Test func schedulerMatchesReferenceVectors() throws {
        let fixture = try loadFixture()
        #expect(fixture.generator.tool == "ts-fsrs")
        #expect(fixture.generator.version == "6.0.0")
        #expect(fixture.generator.fuzz == false)
        #expect(fixture.generator.weights == FSRSModel.defaultWeights)

        let scheduler = FSRSScheduler()
        #expect(fixture.scenarios.count >= 12)

        for scenario in fixture.scenarios {
            let first = try date(scenario.steps[0].ts)
            var card = FSRSCard.new(now: first)

            for (index, step) in scenario.steps.enumerated() {
                let now = try date(step.ts)
                let grade = try #require(Grade(rawValue: step.grade))
                let expected = step.card

                // Pre-review observables.
                let beforeState = try #require(FSRSStateKind(rawValue: step.stateBefore))
                #expect(card.state == beforeState, "\(scenario.name) step \(index): state before")
                close(
                    scheduler.retrievability(of: card, at: now),
                    step.retrievabilityBefore,
                    context: "\(scenario.name) step \(index): retrievability"
                )

                let review = scheduler.review(card, at: now, grade: grade)

                // The elapsed-days convention the reference scheduler uses.
                #expect(
                    review.elapsedDays == step.elapsedDaysBefore,
                    "\(scenario.name) step \(index): elapsed \(review.elapsedDays) vs \(step.elapsedDaysBefore)"
                )

                // Memory state to 1e-4 relative.
                close(review.card.stability, expected.stability, context: "\(scenario.name) step \(index): S")
                close(review.card.difficulty, expected.difficulty, context: "\(scenario.name) step \(index): D")

                // Exact scheduling fields.
                #expect(
                    review.card.scheduledDays == expected.scheduledDays,
                    "\(scenario.name) step \(index): scheduledDays"
                )
                #expect(review.card.reps == expected.reps, "\(scenario.name) step \(index): reps")
                #expect(review.card.lapses == expected.lapses, "\(scenario.name) step \(index): lapses")
                #expect(review.card.learningStep == expected.learningSteps, "\(scenario.name) step \(index): step idx")
                #expect(
                    review.card.state == FSRSStateKind(rawValue: expected.state),
                    "\(scenario.name) step \(index): state after"
                )

                let expectedDue = try date(expected.due)
                #expect(
                    abs(review.card.due.timeIntervalSince(expectedDue)) < 0.5,
                    "\(scenario.name) step \(index): due"
                )
                if let lastReviewISO = expected.lastReview {
                    #expect(abs(review.card.lastReview!.timeIntervalSince(try date(lastReviewISO))) < 0.5)
                }

                card = review.card
            }

            if let probes = scenario.retrievabilityProbes {
                for probe in probes {
                    close(
                        scheduler.retrievability(of: card, at: try date(probe.ts)),
                        probe.value,
                        context: "\(scenario.name) probe"
                    )
                }
            }
        }
    }

    @Test func modelFormulasMatchReferenceVectors() throws {
        // Direct spot checks of the named SPEC §10 formulas against values from
        // the same reference run: New + Easy initialises S = w[3], D clamps to 1,
        // and the interval at 0.9 desired retention equals round(S).
        let model = FSRSModel()
        close(model.initStability(.easy), 8.2956, context: "initStability(easy)")
        #expect(model.initDifficulty(.easy) < 1, "unclamped init difficulty for easy is below 1")
        #expect(model.nextInterval(stability: 8.2956, desiredRetention: 0.9) == 8)
        #expect(model.nextInterval(stability: 2.3065, desiredRetention: 0.9) == 2)
        // R(S, S) = 0.9 exactly under the FSRS-6 factor convention.
        close(model.retrievability(elapsedDays: 8.2956, stability: 8.2956), 0.9, context: "R(S)")
    }
}
